const C = $('Configuration').first().json;
const jour = (d) => d ? new Date(d).toLocaleDateString('fr-CA', { timeZone: 'Europe/Paris' }) : '';
const auj = jour(new Date());
const hier = jour(new Date(Date.now() - 86400000));
const il7 = jour(new Date(Date.now() - 6 * 86400000));
const envois = $('Lire les envois').all().map(i => i.json).filter(e => e.id);
const ouverts = new Set($('Lire les ouvertures').all().map(i => Number(i.json.envoi_id)).filter(Boolean));
function stats(filtre) {
  const l = envois.filter(e => filtre(jour(e.date_decision)));
  const env = l.filter(e => e.statut === 'envoye');
  const ouv = env.filter(e => ouverts.has(Number(e.id))).length;
  return { env: env.length, ouv, pct: env.length ? Math.round(100 * ouv / env.length) : 0,
           relances: env.filter(e => String(e.type).startsWith('relance')).length,
           echecs: l.filter(e => e.statut === 'echec').length,
           tests: l.filter(e => e.statut === 'test').length,
           testsOuv: l.filter(e => e.statut === 'test' && ouverts.has(Number(e.id))).length };
}
const a = stats(d => d === auj), h = stats(d => d === hier), s = stats(d => d && d >= il7), t = stats(d => !!d);
const lignes = [
  `📬 Bilan Nūr Meet du ${new Date().toLocaleDateString('fr-FR', { timeZone: 'Europe/Paris' })}`,
  '',
  `Aujourd'hui : ${a.env} mail(s) envoyé(s)` + (a.relances ? ` dont ${a.relances} relance(s)` : '') + (a.echecs ? `, ${a.echecs} échec(s)` : ''),
  `Hier : ${h.env} envoyé(s), ${h.ouv} ouvert(s) (${h.pct} %)`,
  `7 derniers jours : ${s.env} envoyé(s), ${s.ouv} ouvert(s) (${s.pct} %)`,
  `Depuis le début : ${t.env} envoyé(s), ${t.ouv} ouvert(s) (${t.pct} %)`,
];
if (a.tests || C.MODE_TEST) lignes.push('', `🧪 Mode test : ${a.tests} mail(s) de test envoyé(s) aujourd'hui vers ${C.ADRESSE_TEST}, ${a.testsOuv} ouvert(s).`);
lignes.push('', 'Ouvertures approximatives : certaines messageries bloquent les images, d\'autres les ouvrent automatiquement.');
return [{ json: { texte: lignes.join('\n') } }];
